	@Test
	void retainedEstimateSharesOneActualPayloadAcrossNodesAndContracts() {
		RuntimeFeedbackContract first = contract(new Payload(4_096L));
		RuntimeFeedbackContract second = contract(first.descriptor());
		TupleExpr one = new Join(pattern(), pattern());
		TupleExpr two = one.clone();
		one.setRuntimeFeedbackContract(first);
		((Join) two).getLeftArg().setRuntimeFeedbackContract(first);
		((Join) two).getRightArg().setRuntimeFeedbackContract(second);
		long oneDelta = FactorCostCacheKey.estimatedRetainedBytes(one)
				- FactorCostCacheKey.estimatedRetainedBytes(new Join(pattern(), pattern()));
		long twoDelta = FactorCostCacheKey.estimatedRetainedBytes(two)
				- FactorCostCacheKey.estimatedRetainedBytes(new Join(pattern(), pattern()));
		assertTrue(oneDelta >= 4_096L);
		assertEquals(oneDelta + 160L, twoDelta, "the shared descriptor and prediction singleton objects count once");
		assertEquals(FactorCostCacheKey.estimatedRetainedBytes(new Join(pattern(), pattern())),
				FactorCostCacheKey.estimatedStructuralRetainedBytes(two));
	}

	@Test
	void actualPipelineExactFitRetainsTheChargedPayloadAndOneByteShortRefuses() {
		RuntimeFeedbackContract payload = contract(new Payload(4_096L));
		QueryRoot source = query(payload);
		var context = context();
		long exactBytes;
		LmdbPipelinePlanCache measuring = new LmdbPipelinePlanCache(8, 1, Long.MAX_VALUE);
		try {
			var cold = measuring.getOrCompute(source, context, context::revision, () -> planned(source));
			var hot = measuring.getOrCompute(source, context, context::revision, () -> {
				throw new AssertionError();
			});
			assertSame(payload, cold.plan().getRuntimeFeedbackContract());
			assertTrue(hot.cacheHit());
			assertRetained(hot.plan(), payload);
			exactBytes = measuring.retainedBytes();
			assertTrue(exactBytes >= 4_096L);
			assertSame(payload, source.getRuntimeFeedbackContract());
		} finally {
			measuring.close();
		}
		LmdbPipelinePlanCache exact = new LmdbPipelinePlanCache(8, 1, exactBytes);
		LmdbPipelinePlanCache shortCache = new LmdbPipelinePlanCache(8, 1, exactBytes - 1);
		try {
			exact.getOrCompute(source, context, context::revision, () -> planned(source));
			assertEquals(1, exact.entryCount());
			assertEquals(exactBytes, exact.retainedBytes());
			shortCache.getOrCompute(source, context, context::revision, () -> planned(source));
			assertEquals(0, shortCache.entryCount());
			assertEquals(0, shortCache.retainedBytes());
			assertSame(payload, source.getRuntimeFeedbackContract());
		} finally {
			exact.close();
			shortCache.close();
		}
	}

	@Test
	void completedPipelineFlightCannotRetainAnOffBudgetPayloadForWaiters() throws Exception {
		var cache = new LmdbPipelinePlanCache(8, 1, 1L << 20);
		var context = context();
		RuntimeFeedbackContract payload = contract(new Payload(32_768L));
		QueryRoot source = query(payload);
		CountDownLatch ownerStarted = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		try (var executor = Executors.newFixedThreadPool(2)) {
			var owner = executor.submit(() -> cache.getOrCompute(source, context, context::revision, () -> {
				ownerStarted.countDown();
				await(release);
				return planned(source);
			}));
			try {
				assertTrue(ownerStarted.await(5, TimeUnit.SECONDS));
				var waiter = executor.submit(() -> cache.getOrCompute(source, context, context::revision,
						() -> {
							throw new AssertionError("a successful admitted flight should serve its waiter");
						}));
				long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
				while (cache.waits() == 0 && System.nanoTime() < deadline) {
					Thread.onSpinWait();
				}
				assertEquals(1, cache.waits());
				release.countDown();
				assertSame(payload, owner.get(5, TimeUnit.SECONDS).plan().getRuntimeFeedbackContract());
				var result = waiter.get(5, TimeUnit.SECONDS);
				assertTrue(result.cacheHit());
				assertStripped(result.plan());
			} finally {
				release.countDown();
			}
		} finally {
			cache.close();
		}
	}

