	@Test
	void directBuildRefreshHistoryAndVariantsShareTheActualNativePayloadCharge() {
		RuntimeFeedbackContract payload = contract(new Payload(4_096L));
		QueryRoot source = query(payload);
		Fixture f = new Fixture(source);
		LmdbPlanDecisionCache cache = new LmdbPlanDecisionCache(8, 8_192L);
		try {
			assertTrue(cache.publishBuild(f.build(1_024L)));
			var original = f.use(cache);
			assertRetained(original.plan().materialize(), payload);
			long initialBytes = cache.statistics().retainedBytes();
			assertTrue(initialBytes >= 4_096L);
			assertTrue(cache.publishRefresh(new LmdbPlanDecisionCache.RefreshPublication(f.family,
					original.familyVersion(), f.dependencies, f.evidence, f.evidence, original.variantId(), source,
					"faster", new LmdbPlanDecisionCache.EstimatedCostInterval(1.0d, 1.0d), f.certificate,
					LmdbPlanDecisionCache.PlanStabilityEnvelope.exact(f.evidence), 1_024L, 1L, true)));
			var promoted = f.use(cache);
			assertEquals("faster", promoted.plan().physicalFingerprint());
			assertRetained(promoted.plan().materialize(), payload);
			assertRetained(original.plan().materialize(), payload);
			assertEquals(initialBytes + 1_024L, cache.statistics().retainedBytes(),
					"the actual rollback and champion share the same descriptor and DAG charge");
			var guard = new LmdbPlanDecisionCache.ApplicabilityGuard(new double[] { 1 }, new double[] { 10 },
					0L, 0L, Long.MAX_VALUE, false);
			assertTrue(cache.publishVariant(new LmdbPlanDecisionCache.VariantPublication(f.family,
					promoted.familyVersion(), f.dependencies, f.evidence, f.evidence, 2L, guard, source, "variant",
					new LmdbPlanDecisionCache.EstimatedCostInterval(0.5d, 0.5d), f.certificate,
					new LmdbPlanDecisionCache.PlanStabilityEnvelope(f.evidence,
							guard.minimumCardinalities(), guard.maximumCardinalities(), true),
					512L, 1L)));
			var specialized = assertInstanceOf(LmdbPlanDecisionCache.Use.class,
					cache.lookupFamily(f.family, f.request(new double[] { 5 })));
			assertEquals(2, specialized.variantId());
			assertRetained(specialized.plan().materialize(), payload);
			assertEquals(initialBytes + 1_024L + 512L, cache.statistics().retainedBytes(),
					"specialized variants use the same family identity scope");
			assertSame(payload, source.getRuntimeFeedbackContract());
			assertTrue(cache.statistics().retainedBytes() <= 8_192L);
		} finally {
			cache.close();
		}
	}

